function splitParseItems(text){
  var items=[], lines=String(text||'').split('\n');
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim(); if(!ln) continue;
    var m=ln.match(/^(.*?)\s*([0-9]+(?:\.[0-9]+)?)\s*$/);
    var amount, label;
    if(m){ label=m[1].trim()||('项'+(items.length+1)); amount=Number(m[2]); }
    else { label=ln; amount=NaN; }
    if(!isFinite(amount) || amount<0) return { error:'第 '+(i+1)+' 行金额非法' };
    items.push({ label:label, amount:amount });
  }
  if(!items.length) return { error:'请至少录入一条账单' };
  return { error:null, items:items };
}
function splitCompute(items, opts){
  var people=Number(opts.people);
  if(!(people>=1 && people%1===0)) return { error:'人数须为正整数' };
  var subtotal=0; for(var i=0;i<items.length;i++) subtotal+=items[i].amount;
  var disc=subtotal*(Number(opts.discountPct)||0)/100;
  var after=subtotal-disc;
  var tax=after*(Number(opts.taxPct)||0)/100;
  var tip=after*(Number(opts.tipPct)||0)/100;
  var grand=after+tax+tip;
  return { error:null, subtotal:Math.round(subtotal*100)/100, discount:Math.round(disc*100)/100,
    tax:Math.round(tax*100)/100, tip:Math.round(tip*100)/100, grand:Math.round(grand*100)/100,
    perPerson:Math.round(grand/people*100)/100, count:items.length };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { splitParseItems:splitParseItems, splitCompute:splitCompute };
}
if (typeof window !== 'undefined') {
  window.SplitForgePure = { splitParseItems:splitParseItems, splitCompute:splitCompute };
}
